class TestBranchCounting:
    """Validate branch detection and complexity calculation."""

    def test_branching_function(self, analyzer, branching_function_source):
        """Verify all branch types are counted."""
        result = analyzer.analyze_source(branching_function_source)
        meta = result["process"]
        # for (1) + if/else (2) + while (1) + except (1) = 5 branches
        assert meta.branches == 5
        assert meta.complexity == 6

    def test_if_elif_else_counting(self, analyzer):
        """Verify elif chains count as separate branches."""
        source = """
def classify(x):
    if x < 0:
        return "negative"
    elif x == 0:
        return "zero"
    else:
        return "positive"
"""
        result = analyzer.analyze_source(source)
        # if + elif + else = 3 branches
        assert result["classify"].branches == 3
        assert result["classify"].complexity == 4

    def test_nested_branches_counting(self, analyzer):
        """Nested if statements should each count."""
        source = """
def validate(x, y):
    if x > 0:
        if y > 0:
            return True
    return False
"""
        result = analyzer.analyze_source(source)
        assert result["validate"].branches == 2
        assert result["validate"].complexity == 3

    def test_try_except_else_finally(self, analyzer):
        """Verify try/except/else/finally branch handling."""
        source = """
def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        result = 0
    except TypeError:
        result = -1
    else:
        result = result * 2
    finally:
        pass
    return result
"""
        result = analyzer.analyze_source(source)
        # 2 except handlers = 2 branches
        assert result["safe_divide"].branches == 2
        assert result["safe_divide"].complexity == 3

    def test_comprehension_not_counted(self, analyzer):
        """List comprehensions should not count as branches."""
