class TestIntegration:
    """End-to-end analysis scenarios."""

    def test_complex_module_analysis(self, analyzer):
        """Analyze a realistic module with multiple constructs."""
        source = '''
import os
from typing import List, Optional

class DataProcessor:
    def __init__(self, data: List[int]):
        self.data = data

    def process(self, threshold: int = 0) -> Optional[int]:
        total = 0
        for item in self.data:
            if item > threshold:
                total += item
            else:
                total -= item
        try:
            result = total / len(self.data)
        except ZeroDivisionError:
            result = None
        return result

def helper(x: int) -> int:
    while x > 0:
        x -= 1
    return x
'''
        result = analyzer.analyze_source(source)
        
        # Verify all functions captured
        assert set(result.keys()) == {"__init__", "process", "helper"}
        
        # Verify __init__ analysis
        assert result["__init__"].args == ["self", "data"]
        assert result["__init__"].branches == 0
        
        # Verify process analysis
        assert result["process"].args == ["self", "threshold"]
        assert result["process"].returns == "Optional[int]"
        assert result["process"].branches == 3  # for + if/else + except
        assert result["process"].complexity == 4
        
        # Verify helper analysis
        assert result["helper"].args == ["x"]
        assert result["helper"].returns == "int"
        assert result["helper"].branches == 1  # while
        assert result["helper"].complexity == 2

    def test_repeated_analysis(self, analyzer, simple_function_source):
        """Analyzer should be reusable across multiple calls."""
        result1 = analyzer.analyze_source(simple_function_source)
        result2 = analyzer.analyze_source(simple_function_source)
        assert result1 == result2
        assert len(result1) == 1
        assert len(result2) == 1

    def test_analyzer_state_reset(self, analyzer):
        """State should reset between analyze_source calls."""
        source1 = "def foo():\n    pass\n"
        source2 = "def bar(x):\n    if x:\n        return 1\n    return 0\n"
        
        result1 = analyzer.analyze_source(source1)
        assert set(result1.keys()) == {"foo"}
        
        result2 = analyzer.analyze_source(source2)
        assert set(result2.keys()) == {"bar"}
        assert "foo" not in result2  # No stale state


