# Property-Based Tests (using hypothesis if available)
# ---------------------------------------------------------------------------
class TestPropertyBased:
    """Property-based validation for robustness."""

    def test_complexity_always_positive(self, analyzer):
        """Complexity should always be >= 1."""
        import random
        import string
        
        for _ in range(20):
            # Generate random function names and bodies
            func_name = ''.join(random.choices(string.ascii_lowercase, k=5))
            num_args = random.randint(0, 5)
            args = ', '.join(f'arg{i}' for i in range(num_args))
            
            # Randomly add branches
            branches = []
            for _ in range(random.randint(0, 3)):
                branches.append(f"    if arg0:\n        pass\n")
            
            source = f"def {func_name}({args}):\n" + ''.join(branches) + "    return None\n"
            
            result = analyzer.analyze_source(source)
            meta = result[func_name]
            assert meta.complexity >= 1
            assert meta.branches >= 0
            assert meta.complexity == meta.branches + 1

    def test_branch_count_matches_ast(self, analyzer):
        """Branch count should match manual AST walk."""
        source = """
def complex_func(a, b, c):
    if a:
        if b:
            return 1
    elif c:
        return 2
    else:
        return 3
    for i in range(10):
        pass
    while a:
        break
    try:
        pass
    except Exception:
        pass
"""
        # Manual AST walk
        tree = ast.parse(source)
        manual_count = 0
        for node in ast.walk(tree):
            if isinstance(node, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                manual_count += 1
        
        result = analyzer.analyze_source(source)
        assert result["complex_func"].branches == manual_count
        assert result["complex_func"].complexity == manual_count + 1